/**
 * AUTO-GENERATED automation — created by the spell-automation-generate skill
 * from spell-automation-proposals.md (2026-07-06).
 * Regenerated against the attack/save roll events.
 * Proposal feasibility: needs-gm-or-rights (writing the "no healing" / undead
 *   marker to a target the caster does not own) — now served by applyEffectToActor.
 * Degraded parts (manual): applying the no-healing marker when the caster
 *   neither owns the target's actor nor has a GM online (applyEffectToActor
 *   returns false — logged to console), and hit resolution when the target's AC
 *   is unknown (hit undefined — the marker is skipped). The healing suppression
 *   itself is a visible tracked marker (dnd5e has no HP-regain-blocking field),
 *   so its rule is enforced by reading the tag.
 *
 * Review before trusting. Regenerating this spell OVERWRITES this file.
 * To adopt as manually maintained: remove this banner and the `autogenerated`
 * flag in the definition below — regeneration will then refuse to touch it.
 */

import {MODULE_ID} from '../../framework/constants.js';
import {applyEffectToActor} from '../../framework/utils.js';

/**
 * Chill Touch — a necrotic cantrip. The spell attack roll and necrotic damage
 * resolve vanilla and are never blocked. On a hit, the target is marked so it
 * can't regain hit points until the caster's next turn. Rules versions differ:
 *   - PHB'24: the "no healing" lasts until the END of your next turn; no undead
 *     clause.
 *   - PHB'14: the "no healing" lasts until the START of your next turn, and if the
 *     target is undead it additionally has disadvantage on attack rolls against
 *     the caster until the end of your next turn.
 * The version can't be inferred from a spell item, so it is a per-item setting.
 *
 * HOW IT WORKS:
 *   - `attackRollComplete` fires on the caster's client for Chill Touch's own
 *     attack, reporting hit/miss per target. For each hit target the automation
 *     applies a "Can't Regain Hit Points (Chill Touch)" marker via
 *     applyEffectToActor — written directly when the caster owns the target, or
 *     relayed to the active GM otherwise. The marker carries the caster's uuid and,
 *     for PHB'14 undead, an `undead` flag, so effect-scope routing can react to the
 *     marked creature's later attacks.
 *   - `attackRollConfigure` fires on the ATTACKER's client and reaches this
 *     automation by effect scope when a marked undead makes an attack. If that
 *     attack targets the caster (matched by the stored casterUuid), a disadvantage
 *     is set on the roll. Never cancels the roll.
 *
 * The no-healing rule is a marker only: dnd5e has no HP-regain-blocking change, so
 * the tag is visible and the table enforces the suppression by reading it.
 *
 * DEGRADES SILENTLY (see banner) when:
 *   - the target's AC is unknown, so hit/miss cannot be determined (hit undefined);
 *   - applyEffectToActor returns false (caster lacks ownership AND no GM online).
 * The marker is skipped; write failures are logged to console.
 *
 * Per-item settings (Manage Automations on the spell):
 *   - rulesVersion: '24' (default, no healing until END of your next turn) or
 *     '14' (until START of your next turn, plus the undead disadvantage clause).
 *   - undeadDisadvantage: PHB'14 only — whether marked undead get disadvantage on
 *     attacks against the caster. Ignored under PHB'24.
 */

const NO_HEAL_EFFECT_NAME = 'Can\'t Regain Hit Points (Chill Touch)';

/** Reading a target's creature type is always safe (replicated data). */
function isUndead(actor) {
    const type = actor?.system?.details?.type?.value;
    return typeof type === 'string' && type.toLowerCase() === 'undead';
}

/**
 * Build the no-healing marker. Module-flagged so the GM relay accepts the write and
 * so the marked creature participates in effect-scope routing (for PHB'14 undead).
 * `undead` records whether the disadvantage clause applies; `casterUuid` lets the
 * attackRollConfigure handler match attacks aimed at the caster. Duration ~1 round
 * approximates "until the start/end of the caster's next turn".
 */
function buildNoHealEffect(item, {untilStart, casterUuid, undead}) {
    const when = untilStart ? 'start' : 'end';
    return {
        name: NO_HEAL_EFFECT_NAME,
        img: item.img,
        description: `This creature can't regain hit points until the ${when} of the caster's next turn.`
            + (undead ? ' As undead, it also has disadvantage on attack rolls against the caster.' : '')
            + ' (Marker only — enforce the healing suppression manually.)',
        duration: {rounds: 1},
        flags: {
            [MODULE_ID]: {
                chillTouch: {casterUuid, undead: undead === true},
                // The marker shares nothing with the spell item, but keep the manager
                // from ever name-matching this automation onto the effect.
                disabledAutomations: ['chillTouch']
            }
        }
    };
}

/**
 * Fires on the caster's client after Chill Touch's own attack roll evaluates, with
 * per-target hit/miss. For each hit target, apply the no-healing marker (recording
 * the caster's uuid and, for PHB'14, the undead clause). The attack and damage stay
 * vanilla — nothing here touches the roll.
 */
async function onAttack(context) {
    const {actor, item} = context;
    if (!actor || !item) return;

    const version = context.settings?.rulesVersion ?? '24';
    const undeadOn = context.settings?.undeadDisadvantage !== false;
    const untilStart = version === '14';
    const handleUndead = version === '14' && undeadOn;

    const targets = context.targets ?? [];
    if (!targets.length) return;

    for (const target of targets) {
        if (target.hit === false) continue; // clean miss — nothing to do
        // AC unknown: hit is undefined, so we can't tell hit from miss —
        // leave the marker to the GM rather than guessing.
        if (target.hit === undefined) continue;

        // Confirmed hit.
        const targetActor = target.actor;
        const undead = handleUndead && isUndead(targetActor);
        const effectData = buildNoHealEffect(item, {untilStart, casterUuid: actor.uuid, undead});
        const result = targetActor ? await applyEffectToActor(targetActor, effectData) : false;
        if (result === false) {
            // No ownership of the target's actor and no GM online (or no actor).
            console.warn(`${MODULE_ID} | chillTouch: could not apply "${NO_HEAL_EFFECT_NAME}" to ${target.name}`);
        }
    }
}

/**
 * Read the active Chill Touch marker data off an actor, if any.
 * @returns {{casterUuid: string|null, undead: boolean}|null}
 */
function markerData(actor) {
    if (!actor) return null;
    const effects = actor.appliedEffects ?? actor.effects ?? [];
    for (const effect of effects) {
        const data = effect.flags?.[MODULE_ID]?.chillTouch;
        if (data) return {casterUuid: data.casterUuid ?? null, undead: data.undead === true};
    }
    return null;
}

/**
 * Runs synchronously on the ATTACKER's client, before the attack roll is
 * evaluated. Reached by effect scope because the attacker carries a Chill Touch
 * marker. For PHB'14 undead: if the attack targets the caster who marked them, set
 * disadvantage on the roll. Never cancels the roll.
 */
function applyUndeadDisadvantage(context) {
    const {actor} = context;
    const marker = markerData(actor);
    if (!marker?.undead || !marker.casterUuid) return;

    // Only when this undead is attacking the very caster that marked it.
    const targets = context.targets ?? [];
    const attackingCaster = targets.some(target => target.actor?.uuid === marker.casterUuid);
    if (!attackingCaster) return;

    const roll = context.config?.rolls?.[0];
    if (!roll) return; // Roll structure unparseable — leave the vanilla roll untouched.
    roll.options ??= {};
    roll.options.disadvantage = true;
}

export const chillTouch = {
    id: 'chillTouch',
    name: 'Chill Touch',
    description: 'On a hit, applies a self-expiring "Can\'t Regain Hit Points (Chill Touch)" marker to the target (until the start [PHB\'14] or end [PHB\'24] of the caster\'s next turn), written directly when the caster owns the target or relayed to a GM otherwise. For PHB\'14 undead targets, the marker also causes disadvantage on their attacks against the caster, applied automatically on the attacker\'s client via effect-scope routing. The attack and necrotic damage stay fully vanilla. The no-healing rule is a visible marker only (no dnd5e change encodes it). The marker is skipped when the effect can\'t be written or the target\'s AC is unknown. Set the rules version per item.',
    version: '1.2.0',
    autogenerated: true,
    settings: [
        {
            key: 'rulesVersion',
            name: 'Rules version',
            hint: 'PHB\'24: no healing until the END of your next turn. PHB\'14: until the START of your next turn, '
                + 'plus undead get disadvantage on attacks against you.',
            type: 'select',
            default: '24',
            choices: {
                '24': 'PHB\'24 (end of next turn)',
                '14': 'PHB\'14 (start of next turn + undead clause)'
            }
        },
        {
            key: 'undeadDisadvantage',
            name: 'Undead disadvantage (PHB\'14)',
            hint: 'PHB\'14 only: marked undead attacking the caster roll with disadvantage. Ignored under PHB\'24.',
            type: 'checkbox',
            default: true
        }
    ],
    match: {
        itemNames: ['Chill Touch']
    },
    events: [
        // Item-lifecycle: only Chill Touch's OWN attack may apply the marker.
        // Without the scope, any attack by or against a marked creature routed
        // here via effect scope and applied no-heal markers to that attack's
        // targets.
        {
            event: 'attackRollComplete',
            handler: onAttack,
            priority: 50,
            scopes: ['item']
        },
        // Marker-driven: routed by the chillTouch marker on the attacking undead.
        {
            event: 'attackRollConfigure',
            handler: applyUndeadDisadvantage,
            priority: 50,
            scopes: ['effect']
        }
    ]
};
